<template>
  <div class="tote-manager">
    <div class="opt-intro">
      <div>
        <h2>Tote inventory</h2>
        <p class="opt-desc">
          The physical totes on the floor (their printed/QR labels). Every processing
          record must reference a tote that lives here — this is the source of truth
          for valid tote IDs. Retire a tote instead of deleting it once it has history.
        </p>
      </div>
    </div>

    <!-- Summary strip -->
    <div class="tote-summary">
      <span class="sum-chip"><strong>{{ totes.length }}</strong> totes</span>
      <span class="sum-chip is-active"><strong>{{ countBy('active') }}</strong> active</span>
      <span class="sum-chip is-maint"><strong>{{ countBy('maintenance') }}</strong> maintenance</span>
      <span class="sum-chip is-retired"><strong>{{ countBy('retired') }}</strong> retired</span>
      <span class="sum-chip"><strong>{{ totalTrips }}</strong> trips logged</span>
    </div>

    <Transition name="banner">
      <div v-if="error" class="banner banner-error"><AppIcon name="alert-circle" :size="18" />{{ error }}</div>
    </Transition>

    <!-- Add tote -->
    <form class="tote-add" @submit.prevent="add">
      <input v-model.trim="newTote.tote_id" placeholder="Tote ID (e.g., T100)" :disabled="busy" maxlength="64" />
      <input v-model.trim="newTote.comments" placeholder="Comments (optional)" :disabled="busy" maxlength="240" />
      <button type="submit" class="btn btn-primary btn-sm" :disabled="busy || !newTote.tote_id">
        <AppIcon name="plus" :size="16" />Add Tote
      </button>
    </form>

    <EmptyState v-if="loading && !totes.length" loading message="Loading inventory…" compact />
    <EmptyState v-else-if="!totes.length" icon="box" message="No totes in the inventory yet." compact />

    <div v-else class="table-wrap no-margin">
      <table class="data-table tote-table">
        <thead>
          <tr>
            <th>Tote</th>
            <th>Status</th>
            <th class="num">Trips</th>
            <th>Last used</th>
            <th class="has-comment-cell"></th>
            <th class="actions-col"></th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="t in totes" :key="t.tote_id" class="tote-row" :class="{ dimmed: t.status === 'retired' }"
            @click="openDetail(t)" tabindex="0" @keyup.enter="openDetail(t)">
            <td class="tote-id-cell"><AppIcon name="box" :size="15" />{{ t.tote_id }}</td>
            <td>
              <select class="status-select" :class="`status-${t.status}`" :value="t.status"
                :disabled="busy" @click.stop @change="changeStatus(t, $event.target.value)">
                <option value="active">Active</option>
                <option value="maintenance">Maintenance</option>
                <option value="retired">Retired</option>
              </select>
            </td>
            <td class="num">{{ t.trip_count }}</td>
            <td class="date-cell">{{ fmtDate(t.last_used_at) }}</td>
            <td class="has-comment-cell">
              <AppIcon v-if="t.comments" name="info" :size="15" :title="t.comments" />
            </td>
            <td class="actions-col">
              <button class="icon-btn icon-btn-danger" @click.stop="remove(t)" :disabled="busy"
                :aria-label="`Delete ${t.tote_id}`" title="Delete (only if no history)">
                <AppIcon name="trash" :size="16" />
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- Detail modal -->
    <BaseModal v-if="selected" :title="`Tote ${selected.tote_id}`" @close="attemptClose">
      <div class="tote-detail">
        <!-- Identity + live status -->
        <div class="detail-hero" :class="`accent-${detailStatus}`" style="--i: 0">
          <span class="detail-mark"><AppIcon name="box" :size="24" /></span>
          <div class="detail-hero-text">
            <span class="detail-eyebrow">Physical tote · traceability</span>
            <span class="detail-name">{{ selected.tote_id }}</span>
          </div>
          <span class="detail-status-tag"><span class="tag-dot"></span>{{ statusLabel(detailStatus) }}</span>
        </div>

        <!-- Stat strip -->
        <div class="detail-stats" style="--i: 1">
          <div class="stat">
            <span class="stat-value">{{ selected.trip_count }}</span>
            <span class="stat-label"><AppIcon name="refresh" :size="13" />Trips logged</span>
          </div>
          <div class="stat">
            <span class="stat-value stat-value-sm">{{ fmtRelative(selected.last_used_at) }}</span>
            <span class="stat-label"><AppIcon name="clock" :size="13" />Last used</span>
          </div>
          <div class="stat">
            <span class="stat-value stat-value-sm">{{ fmtDate(selected.created_at, true) }}</span>
            <span class="stat-label"><AppIcon name="history" :size="13" />In inventory since</span>
          </div>
        </div>

        <!-- Status control -->
        <div class="detail-field" style="--i: 2">
          <span class="field-label">Status</span>
          <div class="seg" role="group" aria-label="Tote status">
            <button v-for="s in statusOptions" :key="s.value" type="button"
              class="seg-btn" :class="[`seg-${s.value}`, { active: detailStatus === s.value }]"
              :aria-pressed="detailStatus === s.value" :disabled="busy" @click="detailStatus = s.value">
              <span class="seg-dot"></span>{{ s.label }}
            </button>
          </div>
          <p v-if="detailStatus !== 'active'" class="field-hint">
            <AppIcon name="info" :size="14" />
            {{ detailStatus === 'maintenance'
              ? 'Won’t accept new processing records while under maintenance.'
              : 'Retired totes are kept for history but can’t take new records.' }}
          </p>
        </div>

        <!-- Comments -->
        <div class="detail-field" style="--i: 3">
          <label class="field-label" :for="`tote-comments-${selected.tote_id}`">
            Comments <span class="field-count">{{ (detailComments || '').length }}/240</span>
          </label>
          <textarea :id="`tote-comments-${selected.tote_id}`" v-model.trim="detailComments"
            rows="3" maxlength="240" placeholder="Notes about this tote — condition, repairs, damage…" :disabled="busy" />
        </div>

        <Transition name="banner">
          <div v-if="error" class="banner banner-error"><AppIcon name="alert-circle" :size="18" />{{ error }}</div>
        </Transition>

        <div class="detail-actions">
          <span v-if="detailDirty" class="unsaved-hint">Unsaved changes</span>
          <button class="btn btn-ghost" @click="attemptClose" :disabled="busy">Cancel</button>
          <button class="btn btn-primary" @click="saveDetail" :disabled="busy || !detailDirty">
            <span v-if="busy" class="spinner"></span>
            <AppIcon v-else name="check-circle" :size="16" />
            {{ busy ? 'Saving…' : 'Save changes' }}
          </button>
        </div>
      </div>
    </BaseModal>
  </div>
</template>

<script>
import AppIcon from '@/components/icons/AppIcon.vue'
import EmptyState from '@/components/EmptyState.vue'
import BaseModal from '@/components/BaseModal.vue'

export default {
  name: 'ConfigTotes',
  components: { AppIcon, EmptyState, BaseModal },
  data() {
    return {
      totes: [],
      loading: false,
      busy: false,
      error: null,
      newTote: { tote_id: '', comments: '' },
      selected: null,          // tote shown in the detail modal
      detailStatus: 'active',
      detailComments: '',
      statusOptions: [
        { value: 'active', label: 'Active' },
        { value: 'maintenance', label: 'Maintenance' },
        { value: 'retired', label: 'Retired' },
      ],
    }
  },
  computed: {
    totalTrips() { return this.totes.reduce((sum, t) => sum + Number(t.trip_count || 0), 0) },
    detailDirty() {
      if (!this.selected) return false
      return this.detailStatus !== this.selected.status ||
        (this.detailComments || '') !== (this.selected.comments || '')
    },
  },
  methods: {
    countBy(status) { return this.totes.filter(t => t.status === status).length },

    async fetchTotes() {
      this.loading = true
      this.error = null
      try {
        const res = await fetch('/api/tote-assets')
        if (!res.ok) throw new Error(`Error ${res.status}`)
        this.totes = (await res.json()).totes || []
      } catch (err) { this.error = err.message } finally { this.loading = false }
    },

    async add() {
      if (!this.newTote.tote_id) return
      this.busy = true
      this.error = null
      try {
        const res = await fetch('/api/tote-assets', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ tote_id: this.newTote.tote_id, comments: this.newTote.comments || null }),
        })
        if (!res.ok) { const e = await res.json(); throw new Error(e.error || `Error ${res.status}`) }
        this.newTote = { tote_id: '', comments: '' }
        await this.fetchTotes()
      } catch (err) { this.error = err.message } finally { this.busy = false }
    },

    async changeStatus(tote, status) {
      if (status === tote.status) return
      this.busy = true
      this.error = null
      try {
        const res = await fetch(`/api/tote-assets/${encodeURIComponent(tote.tote_id)}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status }),
        })
        if (!res.ok) { const e = await res.json(); throw new Error(e.error || `Error ${res.status}`) }
        await this.fetchTotes()
      } catch (err) { this.error = err.message; await this.fetchTotes() } finally { this.busy = false }
    },

    statusLabel(v) { return (this.statusOptions.find(s => s.value === v) || {}).label || v },

    openDetail(tote) {
      this.selected = tote
      this.detailStatus = tote.status
      this.detailComments = tote.comments || ''
      this.error = null
    },
    closeDetail() { this.selected = null; this.error = null },
    attemptClose() {
      if (this.busy) return
      if (this.detailDirty && !confirm('Discard unsaved changes to this tote?')) return
      this.closeDetail()
    },

    async saveDetail() {
      if (!this.selected || !this.detailDirty) return
      this.busy = true
      this.error = null
      try {
        const res = await fetch(`/api/tote-assets/${encodeURIComponent(this.selected.tote_id)}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: this.detailStatus, comments: this.detailComments || null }),
        })
        if (!res.ok) { const e = await res.json(); throw new Error(e.error || `Error ${res.status}`) }
        await this.fetchTotes()
        this.closeDetail()
      } catch (err) { this.error = err.message } finally { this.busy = false }
    },

    async remove(tote) {
      const msg = tote.trip_count > 0
        ? `"${tote.tote_id}" has ${tote.trip_count} processing record(s) and can't be deleted. Retire it instead.`
        : `Delete tote "${tote.tote_id}" from the inventory?`
      if (tote.trip_count > 0) { alert(msg); return }
      if (!confirm(msg)) return
      this.busy = true
      this.error = null
      try {
        const res = await fetch(`/api/tote-assets/${encodeURIComponent(tote.tote_id)}`, { method: 'DELETE' })
        if (!res.ok) { const e = await res.json(); throw new Error(e.error || `Error ${res.status}`) }
        await this.fetchTotes()
      } catch (err) { this.error = err.message } finally { this.busy = false }
    },

    fmtDate(dateString, dateOnly = false) {
      if (!dateString) return '—'
      const opts = dateOnly
        ? { year: 'numeric', month: 'short', day: 'numeric' }
        : { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }
      return new Date(dateString).toLocaleString('en-GB', opts)
    },
    fmtRelative(dateString) {
      if (!dateString) return 'Never'
      const diff = Date.now() - new Date(dateString).getTime()
      const mins = Math.round(diff / 6e4)
      if (mins < 1) return 'Just now'
      if (mins < 60) return `${mins}m ago`
      const hrs = Math.round(mins / 60)
      if (hrs < 24) return `${hrs}h ago`
      const days = Math.round(hrs / 24)
      if (days < 30) return `${days}d ago`
      return this.fmtDate(dateString, true)
    },
  },
  mounted() { this.fetchTotes() },
}
</script>

